x;justify-content:flex-end;gap:10mm;padding:3.5mm 18mm 0 0;font-size:11.5px}.section-subtotal span:first-child{color:#4f5963}.section-subtotal b{min-width:28mm;text-align:right}.labor{margin:7mm 14mm 0}.labor h3{margin:0 0 2.5mm;color:#ff6702;font-size:13.5px}.laborline{border-left:3px solid #ff6702;padding:2.5mm 4mm;min-height:9mm;font-size:11.7px;display:flex;align-items:center;justify-content:space-between;gap:10mm}.labor-description{flex:1}.labor-value{display:flex;align-items:center;gap:7mm;white-space:nowrap;color:#4f5963}.labor-value b{color:#202124;min-width:28mm;text-align:right}.bottom{display:grid;grid-template-columns:1fr 70mm;gap:16mm;margin:8mm 14mm 27mm;align-items:start}.notes h3{margin:0 0 3mm;color:#ff6702;font-size:12.5px}.notes p{margin:0;white-space:pre-line;color:#4f565d;font-size:10.5px;line-height:1.5}.summary{font-size:11.5px}.summary .r{display:flex;justify-content:space-between;gap:8mm;padding:2.5mm 0}.summary .grand{border-top:1px solid #333;margin-top:3mm;padding-top:4mm;color:#ff6702;font-size:19px;font-weight:700}.footerbrand{position:absolute;left:14mm;bottom:10mm;color:#ff6702;font-weight:700;font-size:11.5px}.footnote{position:absolute;right:14mm;bottom:10mm;text-align:right;font-size:9.5px;color:#4d4d4d}.bottom-art{position:absolute;right:0;bottom:0;width:82mm;height:25mm;display:block}.screen-note{width:210mm;margin:0 auto 18px;background:#fff;border:1px solid #ddd;padding:10px 14px;font-size:12px}
